import numpy as np

def get_row_sum(row_num):
    row = np.zeros(row_num)
    row[0] = 1
    for i in range(1, row_num):
        row[i] = 1
        for j in range(i):
            row[i] += row[j]
    return row

def get_units_digit(row_num):
    row = get_row_sum(row_num)
    return row[-1] % 10

