import itertools

def is_subset(a, b):
    return set(a).issubset(b)

def count_sequences(n):
    if n == 1:
        return 1

    count = 0
    for i in range(1, n+1):
        for subset in itertools.combinations(range(1, 11), i):
            if all(is_subset(subset, seq) for seq in subset):
                count += 1
    return count

n = 10
print(count_sequences(n))

# The remainder when K is divided by 10 is:
print(count_sequences(n) % 10)

